from collections import Counter
def runs(g, axis):
    # maximal straight runs of minority color
    g=np.array(g); H,W=g.shape
    cnt=Counter(g.flatten()); mc=min(cnt,key=lambda c:cnt[c])
    out=[]
    if axis==0:  # horizontal runs
        for i in range(H):
            j=0
            while j<W:
                if g[i,j]==mc:
                    s=j
                    while j<W and g[i,j]==mc: j+=1
                    L=j-s
                    if L>=2: out.append(('H',i,s,L))
                else: j+=1
    else:
        for j in range(W):
            i=0
            while i<H:
                if g[i,j]==mc:
                    s=i
                    while i<H and g[i,j]==mc: i+=1
                    L=i-s
                    if L>=2: out.append(('V',j,s,L))
                else: i+=1
    return out
